-- Canonical retained-source reconciliation for the subsequent reviewed
-- resolution workflow. This function NEVER releases a hold or posts money.
CREATE INDEX checkout_dispute_cursor_history ON public.checkout_dispute_inspections(academy_id,start_id,(dispute_inspection->>'startingAfter'),received_at DESC,id DESC);
CREATE INDEX checkout_dispute_conflict_cases ON public.checkout_dispute_inspections USING gin((dispute_inspection->'disputes') jsonb_path_ops) WHERE object_conflict;
CREATE FUNCTION public.provider_dispute_resolution_source(p_collection uuid,p_on date DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE c record;principal record;page record;cursor_id text:=NULL;page_complete boolean:=false;page_conflict boolean:=false;page_ids uuid[]:=ARRAY[]::uuid[];case_ids text[]:=ARRAY[]::text[];case_id text;case_rows jsonb;movement_rows jsonb;asset_rows jsonb;history text;bookings jsonb;held boolean;other_hold boolean;case_count integer;pointer_count integer;source jsonb;BEGIN
 SELECT pc.*,q.id checkout_request_id,a.id attempt_id,q.currency_code,q.unit_scale,cl.time_zone,coalesce(p_on,(statement_timestamp() AT TIME ZONE cl.time_zone)::date) on_day INTO c
 FROM public.provider_collections pc JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=pc.academy_id AND st.id=pc.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id JOIN public.payment_checkout_requests q ON q.academy_id=a.academy_id AND q.id=a.request_id JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.id=p_collection;
 IF c.id IS NULL OR c.on_day NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31' THEN RETURN NULL;END IF;
 IF(SELECT count(*) FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id)>10000 OR(SELECT count(*) FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings r ON r.academy_id=x.academy_id AND r.id=x.posting_id WHERE r.academy_id=c.academy_id AND r.collection_id=c.id)>1000 OR(SELECT count(*) FROM public.checkout_dispute_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id)>10000 OR(SELECT count(*) FROM public.checkout_dispute_balance_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id)>10000 THEN RETURN jsonb_build_object('unavailable','DISPUTE_RESOLUTION_REQUIRES_BACKGROUND');END IF;
 IF coalesce((SELECT sum(octet_length(inspection::text)) FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id),0)+coalesce((SELECT sum(octet_length(dispute_inspection::text)) FROM public.checkout_dispute_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id),0)+coalesce((SELECT sum(octet_length(balance_inspection::text)) FROM public.checkout_dispute_balance_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id),0)>16777216 THEN RETURN jsonb_build_object('unavailable','DISPUTE_RESOLUTION_REQUIRES_BACKGROUND');END IF;
 SELECT * INTO principal FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id ORDER BY received_at DESC,id DESC LIMIT 1;
 FOR n IN 1..100 LOOP
  SELECT i.*,p.inspection principal_fact INTO page FROM public.checkout_dispute_inspections i JOIN public.checkout_provider_inspections p ON p.academy_id=i.academy_id AND p.id=i.principal_inspection_id WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND i.dispute_inspection->>'state'='dispute_page' AND(i.dispute_inspection->>'startingAfter') IS NOT DISTINCT FROM cursor_id ORDER BY i.received_at DESC,i.id DESC LIMIT 1;
  EXIT WHEN page.id IS NULL OR page.id=ANY(page_ids) OR page.principal_fact IS DISTINCT FROM principal.inspection OR page.object_conflict;
  page_ids=array_append(page_ids,page.id);
  FOR case_id IN SELECT value->>'id' FROM jsonb_array_elements(page.dispute_inspection->'disputes') LOOP IF case_id=ANY(case_ids) THEN page_conflict=true;EXIT;END IF;case_ids=array_append(case_ids,case_id);END LOOP;
  EXIT WHEN page_conflict;
  IF page.dispute_inspection->'hasMore'='false'::jsonb THEN page_complete=true;EXIT;END IF;cursor_id=page.dispute_inspection->>'nextCursor';
 END LOOP;
 held=EXISTS(SELECT 1 FROM public.checkout_dispute_attention WHERE academy_id=c.academy_id AND start_id=c.start_id AND charge_id=c.charge_id);
 other_hold=EXISTS(SELECT 1 FROM public.checkout_refund_attention WHERE academy_id=c.academy_id AND start_id=c.start_id AND charge_id=c.charge_id);
 WITH facts AS MATERIALIZED(
  SELECT i.id,i.received_at,i.object_conflict,i.dispute_inspection->'providerUnitScale' provider_scale,v.value FROM public.checkout_dispute_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.dispute_inspection->'disputes') v WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
 ),latest AS(SELECT DISTINCT ON(value->>'id') * FROM facts ORDER BY value->>'id',received_at DESC,id DESC LIMIT 101)
 SELECT count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('disputeId',value->>'id','inspectionId',id,'status',value->>'status','amountMinor',value->>'amount','currencyCode',upper(value->>'currency'),'providerUnitScale',CASE WHEN value->>'currency'=lower(c.currency_code) THEN provider_scale ELSE(SELECT i.balance_inspection->'providerUnitScale' FROM public.checkout_dispute_balance_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND i.dispute_id=latest.value->>'id' AND i.balance_inspection->>'currency'=latest.value->>'currency' ORDER BY i.received_at DESC,i.id DESC LIMIT 1) END,
 'ownershipConflict',object_conflict OR EXISTS(SELECT 1 FROM public.checkout_dispute_inspections bad JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=bad.academy_id AND st.id=bad.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id WHERE bad.academy_id=c.academy_id AND bad.object_conflict AND a.draft->>'accountId'=c.account_id AND(a.draft->>'livemode')::boolean=c.livemode AND bad.dispute_inspection->'disputes' @>jsonb_build_array(jsonb_build_object('id',latest.value->>'id'))) OR NOT EXISTS(SELECT 1 FROM public.checkout_dispute_object_bindings b WHERE b.academy_id=c.academy_id AND b.account_id=c.account_id AND b.livemode=c.livemode AND b.dispute_id=latest.value->>'id' AND b.start_id=c.start_id AND b.charge_id=c.charge_id),
 'requiresFxReview',value->'requiresFxReview','exceedsOriginalAmount',value->'exceedsOriginalAmount') ORDER BY value->>'id'),'[]'::jsonb) INTO case_count,case_rows FROM latest;
 IF case_count>100 THEN RETURN jsonb_build_object('unavailable','DISPUTE_RESOLUTION_REQUIRES_BACKGROUND');END IF;
 WITH pointers AS MATERIALIZED(
  SELECT DISTINCT v.value->>'id' dispute_id,p.value transaction_id FROM public.checkout_dispute_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.dispute_inspection->'disputes') v CROSS JOIN LATERAL jsonb_array_elements_text(v.value->'balanceTransactionIds') p WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
  UNION SELECT dispute_id,balance_inspection->>'balanceTransactionId' FROM public.checkout_dispute_balance_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id LIMIT 201
 ),rows AS(
  SELECT wanted.*,e.id inspection_id,e.balance_inspection evidence,e.object_conflict,root.id posting_id,root.posted_on original_on,
   coalesce(edition.posted_on,root.posted_on) effective_on,coalesce(edition.source->'next',root.source) effective,
   coalesce(edition.version,0) version,coalesce(edition.replacement_id,root.id) current_journal,
   EXISTS(SELECT 1 FROM public.provider_dispute_corrections later WHERE later.academy_id=root.academy_id AND later.posting_id=root.id AND later.posted_on>c.on_day) OR root.posted_on>c.on_day future_accounting
  FROM pointers wanted LEFT JOIN LATERAL(SELECT * FROM public.checkout_dispute_balance_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id AND i.dispute_id=wanted.dispute_id AND i.balance_inspection->>'balanceTransactionId'=wanted.transaction_id ORDER BY i.received_at DESC,i.id DESC LIMIT 1) e ON true
  LEFT JOIN public.provider_dispute_postings root ON root.academy_id=c.academy_id AND root.collection_id=c.id AND root.transaction_id=wanted.transaction_id AND root.dispute_id=wanted.dispute_id
  LEFT JOIN LATERAL(SELECT * FROM public.provider_dispute_corrections x WHERE x.academy_id=root.academy_id AND x.posting_id=root.id AND x.posted_on<=c.on_day ORDER BY version DESC LIMIT 1) edition ON true
 ) SELECT count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('disputeId',dispute_id,'balanceTransactionId',transaction_id,'inspectionId',inspection_id,'postingId',posting_id,'accountingVersion',version,'currentJournalId',current_journal,'postedOn',effective_on::text,'futureDatedAccounting',coalesce(future_accounting,false),
  'observed',inspection_id IS NOT NULL,'currencyCode',upper(evidence->>'currency'),'providerUnitScale',evidence->'providerUnitScale','grossMinor',evidence->>'grossAmount','feeMinor',evidence->>'feeAmount','netMinor',evidence->>'netAmount',
  'recognized',coalesce(evidence->'recognizedDisputeAdjustment'='true'::jsonb AND evidence->>'sourceBinding'='dispute',false),'requiresFxReview',coalesce(evidence->'requiresFxReview','false'::jsonb),'amountMatched',coalesce(evidence->'disputeAmountMatched','false'::jsonb),
  'ownershipConflict',coalesce(object_conflict,false) OR EXISTS(SELECT 1 FROM public.checkout_dispute_balance_inspections bad JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=bad.academy_id AND st.id=bad.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id WHERE bad.academy_id=c.academy_id AND bad.object_conflict AND a.draft->>'accountId'=c.account_id AND(a.draft->>'livemode')::boolean=c.livemode AND bad.balance_inspection->>'balanceTransactionId'=rows.transaction_id) OR(inspection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.checkout_balance_object_bindings binding WHERE binding.academy_id=c.academy_id AND binding.account_id=c.account_id AND binding.livemode=c.livemode AND binding.start_id=c.start_id AND binding.charge_id=c.charge_id AND binding.transaction_id=rows.transaction_id)) OR(inspection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.checkout_dispute_balance_bindings binding WHERE binding.academy_id=c.academy_id AND binding.account_id=c.account_id AND binding.livemode=c.livemode AND binding.start_id=c.start_id AND binding.dispute_id=rows.dispute_id AND binding.transaction_id=rows.transaction_id)),
  'accountingMatchesLatest',posting_id IS NOT NULL AND effective_on<=c.on_day AND NOT coalesce(object_conflict,false) AND(SELECT jsonb_object_agg(k,evidence->k) FROM unnest(ARRAY['chargeId','disputeId','balanceTransactionId','balanceType','transactionType','reportingCategory','source','providerUnitScale','grossAmount','currency','feeAmount','netAmount']) k) IS NOT DISTINCT FROM(SELECT jsonb_object_agg(k,effective->'evidence'->k) FROM unnest(ARRAY['chargeId','disputeId','balanceTransactionId','balanceType','transactionType','reportingCategory','source','providerUnitScale','grossAmount','currency','feeAmount','netAmount']) k),
  'disputedAccountId',effective->'disputedAccountId','accountingCurrencyId',effective->'currencyId','accountingCurrencyCode',effective->'currencyCode','accountingUnitScale',effective->'unitScale','accountingGrossMinor',CASE WHEN effective_on<=c.on_day THEN effective->>'grossMinor' ELSE NULL END
 ) ORDER BY dispute_id,transaction_id),'[]'::jsonb) INTO pointer_count,movement_rows FROM rows;
 IF pointer_count>200 THEN RETURN jsonb_build_object('unavailable','DISPUTE_RESOLUTION_REQUIRES_BACKGROUND');END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY "disputeId","accountId","currencyId"),'[]'::jsonb) INTO asset_rows FROM(
  SELECT value->>'disputeId' "disputeId",value->>'disputedAccountId' "accountId",value->>'accountingCurrencyId' "currencyId",value->>'accountingCurrencyCode' "currencyCode",(value->>'accountingUnitScale')::integer "unitScale",trunc(-sum((value->>'accountingGrossMinor')::numeric))::text "balanceMinor"
  FROM jsonb_array_elements(movement_rows) WHERE value->>'accountingGrossMinor' IS NOT NULL GROUP BY value->>'disputeId',value->>'disputedAccountId',value->>'accountingCurrencyId',value->>'accountingCurrencyCode',(value->>'accountingUnitScale')::integer
 ) x;
 -- Hash ordered MATERIAL transitions,not just the latest observation. A late
 -- older response cannot revive an approval after A->B->A;an identical refresh
 -- does not invent a new material transition merely by receiving a new ID.
 WITH facts AS(
  SELECT 'principal'::text stream,i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.inspection) fact FROM public.checkout_provider_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
  UNION ALL SELECT 'page',i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.dispute_inspection) FROM public.checkout_dispute_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
  UNION ALL SELECT 'balance:'||(i.balance_inspection->>'balanceTransactionId'),i.received_at,i.id,jsonb_build_object('conflict',i.object_conflict,'fact',i.balance_inspection-ARRAY['status','availableOn']) FROM public.checkout_dispute_balance_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id
 ),transitions AS(SELECT *,lag(fact) OVER(PARTITION BY stream ORDER BY received_at,id) previous FROM facts)
 SELECT encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(jsonb_build_array(stream,fact)::text,'UTF8')),'hex'),'' ORDER BY stream,received_at,id) FILTER(WHERE fact IS DISTINCT FROM previous),''),'UTF8')),'hex') INTO history FROM transitions;
 SELECT coalesce(jsonb_agg(value ORDER BY family,id),'[]'::jsonb) INTO bookings FROM(
  SELECT 'posting'::text family,r.id,to_jsonb(r) value FROM public.provider_dispute_postings r WHERE r.academy_id=c.academy_id AND r.collection_id=c.id
  UNION ALL SELECT 'correction',x.id,to_jsonb(x) FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings r ON r.academy_id=x.academy_id AND r.id=x.posting_id WHERE r.academy_id=c.academy_id AND r.collection_id=c.id
 ) b;
 source=jsonb_build_object('collectionId',c.id,'on',c.on_day::text,'onIsFuture',c.on_day>(statement_timestamp() AT TIME ZONE c.time_zone)::date,'onPrecedesCollection',c.on_day<c.received_on,'timeZone',c.time_zone,'balanceHistoryPath','/api/v1/finance/checkout-requests/'||c.checkout_request_id::text||'/attempts/'||c.attempt_id::text||'/dispute-balance-inspections','disputeHistoryPath','/api/v1/finance/checkout-requests/'||c.checkout_request_id::text||'/attempts/'||c.attempt_id::text||'/dispute-inspections','originalCurrencyCode',c.currency_code,'disputeAttentionRetained',held,'separateRefundAttentionRetained',other_hold,'principalInspectionId',principal.id,'pageChainComplete',page_complete,'pageChainConflict',page_conflict,'pageCount',cardinality(page_ids),
 'currentPrincipalCaptured',principal.id IS NOT NULL AND NOT principal.object_conflict AND principal.inspection->>'state'='captured' AND principal.inspection->>'chargeId'=c.charge_id AND principal.inspection->'disputed'='false'::jsonb,
 'cases',case_rows,'movements',movement_rows,'disputedAssets',asset_rows,'sourceFingerprint',encode(sha256(convert_to(jsonb_build_object('version',1,'collectionId',c.id,'on',c.on_day,'history',history,'bookings',bookings,'held',held,'otherHold',other_hold,'timeZone',c.time_zone,'futureDay',c.on_day>(statement_timestamp() AT TIME ZONE c.time_zone)::date,'caseState',(SELECT jsonb_agg(value-'inspectionId' ORDER BY value->>'disputeId') FROM jsonb_array_elements(case_rows)),'movementState',(SELECT jsonb_agg(value-'inspectionId' ORDER BY value->>'disputeId',value->>'balanceTransactionId') FROM jsonb_array_elements(movement_rows)))::text,'UTF8')),'hex'));
 RETURN source;
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_resolution_source(uuid,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_resolution_source(uuid,date) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 333 $$;
